const payload = $json.body || {};
const appointment = payload.appointment || {};
const patient = appointment.patient || {};
const professional = appointment.professional || {};

if (payload.event !== 'appointment.confirmed') {
  throw new Error('Evento invalido: esperado appointment.confirmed.');
}

if (!payload.event_id || !appointment.id || !appointment.google_event_id || !appointment.starts_at) {
  throw new Error('Payload incompleto: event_id, appointment.id, google_event_id e starts_at sao obrigatorios.');
}

function whatsappNumber(value, label) {
  let digits = String(value || '').replace(/\D/g, '');

  if (digits.length === 10 || digits.length === 11) {
    digits = `55${digits}`;
  }

  if (digits.length < 12 || digits.length > 13) {
    throw new Error(`Telefone ${label} ausente ou invalido.`);
  }

  return `${digits}@s.whatsapp.net`;
}

if (!patient.name || !professional.name) {
  throw new Error('Payload incompleto: nomes do paciente e do profissional sao obrigatorios.');
}

const professionalEmail = String(professional.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(professionalEmail)) {
  throw new Error('E-mail do profissional ausente ou invalido.');
}

const startsAt = new Date(appointment.starts_at);
if (Number.isNaN(startsAt.getTime())) {
  throw new Error('Data do agendamento invalida.');
}

const date = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  weekday: 'long',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
}).format(startsAt);

const time = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}).format(startsAt);

const specialty = professional.specialty ? ` (${professional.specialty})` : '';

return [{
  json: {
    eventId: payload.event_id,
    appointmentId: appointment.id,
    googleEventId: appointment.google_event_id,
    professionalEmail,
    patientNumber: whatsappNumber(patient.phone, 'do paciente'),
    professionalNumber: whatsappNumber(professional.phone, 'do profissional'),
    patientMessage: `Ola, ${patient.name}! Seu agendamento com ${professional.name}${specialty} foi confirmado para ${date}, as ${time}.\n\nClinica Maieutica`,
    professionalMessage: `Ola, ${professional.name}! Um atendimento foi confirmado para ${date}, as ${time}.\n\nPaciente: ${patient.name}\nContato: ${patient.phone}\n\nClinica Maieutica`,
  },
}];
